_CASCADE_CODE = '"""\nevaluate_path_B_cascade_combined.py — Detector + coarse->fine Path B evaluation.\n\nRuns:\n  1) frozen YOLO detector -> boxes/scores;\n  2) coarse crop classifier -> material class;\n  3) optional fine classifier for the predicted material -> fine class;\n  4) coarse mAP using material labels, and fine mAP when labels_fine exists.\n\nUsage:\n  python evaluate_path_B_cascade_combined.py \\\n    --detector_weights /workspace/runs/path_A/yolov8m/weights/best.pt \\\n    --cascade_dir /workspace/runs/path_B_cascade \\\n    --data_yaml /workspace/processed_5cls/dataset_path_B.yaml \\\n    --output /workspace/results_path_B_cascade \\\n    --device 0\n"""\n\nimport argparse\nimport json\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torchvision.transforms as T\nimport yaml\nfrom PIL import Image\nfrom tqdm import tqdm\nfrom ultralytics import YOLO\nimport timm\n\nCOARSE_CLASSES = ["plastic", "paper", "metal", "glass", "other"]\nIOU_THRESHOLDS = np.linspace(0.5, 0.95, 10)\n\nBACKBONES = {\n    "resnet50": "resnet50.a1_in1k",\n    "vit_b16_scratch": "vit_base_patch16_224",\n    "vit_b16_imagenet": "vit_base_patch16_224.augreg_in21k_ft_in1k",\n}\n\nCROP_TRANSFORM = T.Compose([\n    T.Resize((224, 224)),\n    T.ToTensor(),\n    T.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),\n])\n\n\ndef load_meta(model_dir: Path):\n    meta_path = model_dir / "model_meta.json"\n    if not meta_path.exists():\n        raise FileNotFoundError(f"Missing model metadata: {meta_path}")\n    return json.loads(meta_path.read_text())\n\n\ndef load_timm_classifier(model_dir: Path, device: torch.device) -> tuple[nn.Module, dict]:\n    meta = load_meta(model_dir)\n    backbone = meta["backbone"]\n    model_name = BACKBONES[backbone]\n    model = timm.create_model(model_name, pretrained=False, num_classes=len(meta["class_ids"]))\n    weights = model_dir / "weights" / "best.pt"\n    if not weights.exists():\n        raise FileNotFoundError(f"Missing weights: {weights}")\n    model.load_state_dict(torch.load(weights, map_location=device))\n    model.to(device).eval()\n    print(f"  loaded {model_dir.name}: kind={meta[\'kind\']} backbone={backbone} classes={len(meta[\'class_ids\'])}")\n    return model, meta\n\n\ndef load_cascade(cascade_dir: Path, device: torch.device):\n    coarse_model, coarse_meta = load_timm_classifier(cascade_dir / "coarse", device)\n    fine_models = {}\n    fine_root = cascade_dir / "fine"\n    if fine_root.exists():\n        for child in sorted(fine_root.iterdir()):\n            if child.is_dir() and (child / "weights" / "best.pt").exists():\n                model, meta = load_timm_classifier(child, device)\n                fine_models[meta["parent_coarse_idx"]] = (model, meta)\n    print(f"  fine classifiers loaded: {len(fine_models)}")\n    return coarse_model, coarse_meta, fine_models\n\n\ndef crop_batch(img_pil: Image.Image, boxes_xyxy: np.ndarray):\n    crops = []\n    W, H = img_pil.size\n    for x1, y1, x2, y2 in boxes_xyxy:\n        x1 = max(0, int(x1)); y1 = max(0, int(y1))\n        x2 = min(W, int(x2)); y2 = min(H, int(y2))\n        if x2 <= x1 or y2 <= y1:\n            crops.append(torch.zeros(3, 224, 224))\n            continue\n        crops.append(CROP_TRANSFORM(img_pil.crop((x1, y1, x2, y2)).convert("RGB")))\n    return torch.stack(crops) if crops else torch.zeros(0, 3, 224, 224)\n\n\ndef classify_cascade(img_pil, boxes_xyxy, coarse_model, fine_models, device):\n    if len(boxes_xyxy) == 0:\n        return np.zeros(0, dtype=int), np.zeros(0, dtype=int), np.zeros((0, len(COARSE_CLASSES)), dtype=np.float32)\n    batch = crop_batch(img_pil, boxes_xyxy).to(device)\n    with torch.no_grad():\n        coarse_logits = coarse_model(batch)\n        coarse_probs = torch.softmax(coarse_logits, dim=1)\n        coarse_preds = coarse_probs.argmax(1).cpu().numpy()\n    fine_preds = np.full(len(coarse_preds), -1, dtype=int)\n\n    for coarse_idx in sorted(set(coarse_preds.tolist())):\n        where = np.where(coarse_preds == coarse_idx)[0]\n        if coarse_idx not in fine_models:\n            continue\n        fine_model, fine_meta = fine_models[coarse_idx]\n        with torch.no_grad():\n            logits = fine_model(batch[where])\n            local = logits.argmax(1).cpu().numpy()\n        global_ids = np.array(fine_meta["class_ids"], dtype=int)\n        fine_preds[where] = global_ids[local]\n    return coarse_preds, fine_preds, coarse_probs.cpu().numpy()\n\n\ndef yolo_txt_to_xyxy(label_path: Path, img_size: tuple[int, int]):\n    W, H = img_size\n    boxes, classes = [], []\n    if label_path.exists():\n        text = label_path.read_text().strip()\n        if text:\n            for line in text.splitlines():\n                parts = line.split()\n                if len(parts) < 5:\n                    continue\n                cls_id = int(float(parts[0]))\n                cx, cy, nw, nh = map(float, parts[1:5])\n                x1 = (cx - nw / 2) * W; y1 = (cy - nh / 2) * H\n                x2 = (cx + nw / 2) * W; y2 = (cy + nh / 2) * H\n                boxes.append([x1, y1, x2, y2]); classes.append(cls_id)\n    return (\n        np.array(boxes, dtype=np.float32) if boxes else np.zeros((0, 4), dtype=np.float32),\n        np.array(classes, dtype=int),\n    )\n\n\ndef box_iou_np(a: np.ndarray, b: np.ndarray) -> np.ndarray:\n    if len(a) == 0 or len(b) == 0:\n        return np.zeros((len(a), len(b)), dtype=np.float32)\n    ix1 = np.maximum(a[:, None, 0], b[None, :, 0])\n    iy1 = np.maximum(a[:, None, 1], b[None, :, 1])\n    ix2 = np.minimum(a[:, None, 2], b[None, :, 2])\n    iy2 = np.minimum(a[:, None, 3], b[None, :, 3])\n    inter = np.maximum(0, ix2 - ix1) * np.maximum(0, iy2 - iy1)\n    area_a = np.maximum(0, a[:, 2] - a[:, 0]) * np.maximum(0, a[:, 3] - a[:, 1])\n    area_b = np.maximum(0, b[:, 2] - b[:, 0]) * np.maximum(0, b[:, 3] - b[:, 1])\n    union = area_a[:, None] + area_b[None, :] - inter\n    return inter / (union + 1e-7)\n\n\ndef compute_ap(recalls: np.ndarray, precisions: np.ndarray) -> float:\n    ap = 0.0\n    for r in np.linspace(0, 1, 101):\n        mask = recalls >= r\n        ap += precisions[mask].max() if mask.any() else 0.0\n    return ap / 101\n\n\ndef compute_map(pred_boxes, pred_scores, pred_classes, gt_boxes, gt_classes, num_classes, iou_thresh):\n    all_preds = []\n    for img_i, (boxes, scores, classes) in enumerate(zip(pred_boxes, pred_scores, pred_classes)):\n        for b, s, c in zip(boxes, scores, classes):\n            if int(c) < 0:\n                continue\n            all_preds.append((img_i, float(s), int(c), b))\n    all_preds.sort(key=lambda x: -x[1])\n\n    ap_per_class = np.zeros(num_classes)\n    ar_per_class = np.zeros(num_classes)\n    gt_counts = np.zeros(num_classes, dtype=int)\n\n    for cls in range(num_classes):\n        gt_counts[cls] = sum((gt_classes[i] == cls).sum() for i in range(len(gt_classes)))\n        if gt_counts[cls] == 0:\n            continue\n        cls_preds = [(i, s, b) for i, s, c, b in all_preds if c == cls]\n        if not cls_preds:\n            continue\n        matched = [set() for _ in range(len(gt_boxes))]\n        tp = np.zeros(len(cls_preds)); fp = np.zeros(len(cls_preds))\n        for k, (img_i, _, pred_b) in enumerate(cls_preds):\n            gt_b = gt_boxes[img_i]\n            gt_c = gt_classes[img_i]\n            mask = gt_c == cls\n            cls_gt = gt_b[mask]\n            cls_idx = np.where(mask)[0]\n            if len(cls_gt) == 0:\n                fp[k] = 1\n                continue\n            ious = box_iou_np(pred_b[None], cls_gt)[0]\n            best = int(ious.argmax())\n            if float(ious[best]) >= iou_thresh and int(cls_idx[best]) not in matched[img_i]:\n                tp[k] = 1\n                matched[img_i].add(int(cls_idx[best]))\n            else:\n                fp[k] = 1\n        cum_tp = np.cumsum(tp); cum_fp = np.cumsum(fp)\n        recalls = cum_tp / (gt_counts[cls] + 1e-7)\n        precisions = cum_tp / (cum_tp + cum_fp + 1e-7)\n        ap_per_class[cls] = compute_ap(recalls, precisions)\n        ar_per_class[cls] = recalls.max() if len(recalls) else 0.0\n    return ap_per_class, ar_per_class, gt_counts\n\n\ndef evaluate(args):\n    device = torch.device(f"cuda:{args.device}" if args.device.isdigit() and torch.cuda.is_available() else "cpu")\n    print(f"Device: {device}")\n    args.output.mkdir(parents=True, exist_ok=True)\n\n    with open(args.data_yaml) as f:\n        cfg = yaml.safe_load(f)\n    data_root = Path(cfg["path"])\n    test_img_dir = data_root / cfg.get("test", "test/path_B/images")\n    test_lbl_dir = Path(str(test_img_dir).replace("images", "labels"))\n    test_fine_lbl_dir = test_img_dir.parent / "labels_fine"\n    has_fine_gt = test_fine_lbl_dir.exists()\n    print(f"Test images: {test_img_dir}")\n    print(f"Fine GT labels found: {has_fine_gt} ({test_fine_lbl_dir})")\n\n    maps_path = data_root / "meta" / "fine_class_map.json"\n    fine_classes = []\n    if maps_path.exists():\n        fine_classes = json.loads(maps_path.read_text()).get("fine_classes", [])\n\n    detector = YOLO(str(args.detector_weights))\n    coarse_model, coarse_meta, fine_models = load_cascade(args.cascade_dir, device)\n\n    pred_boxes_all, pred_scores_all, pred_coarse_all, pred_fine_all = [], [], [], []\n    gt_boxes_all, gt_coarse_all, gt_fine_all = [], [], []\n    rows = []\n    img_paths = sorted(test_img_dir.glob("*.jpg"))\n    t0 = time.perf_counter()\n\n    for img_path in tqdm(img_paths, desc="cascade eval"):\n        img_pil = Image.open(img_path).convert("RGB")\n        gt_b, gt_c = yolo_txt_to_xyxy(test_lbl_dir / img_path.with_suffix(".txt").name, img_pil.size)\n        gt_boxes_all.append(gt_b); gt_coarse_all.append(gt_c)\n        if has_fine_gt:\n            gt_fb, gt_fc = yolo_txt_to_xyxy(test_fine_lbl_dir / img_path.with_suffix(".txt").name, img_pil.size)\n            gt_fine_all.append(gt_fc)\n        else:\n            gt_fine_all.append(np.zeros(0, dtype=int))\n\n        result = detector.predict(str(img_path), conf=args.det_conf, iou=args.det_iou, imgsz=args.imgsz, device=str(device.index if device.type == "cuda" else "cpu"), verbose=False)[0]\n        if result.boxes is None or len(result.boxes) == 0:\n            pred_boxes_all.append(np.zeros((0, 4), dtype=np.float32))\n            pred_scores_all.append(np.zeros(0, dtype=np.float32))\n            pred_coarse_all.append(np.zeros(0, dtype=int))\n            pred_fine_all.append(np.zeros(0, dtype=int))\n            continue\n        boxes = result.boxes.xyxy.cpu().numpy()\n        scores = result.boxes.conf.cpu().numpy()\n        coarse_preds, fine_preds, coarse_probs = classify_cascade(img_pil, boxes, coarse_model, fine_models, device)\n        pred_boxes_all.append(boxes); pred_scores_all.append(scores); pred_coarse_all.append(coarse_preds); pred_fine_all.append(fine_preds)\n\n        for i, (b, s, c, f) in enumerate(zip(boxes, scores, coarse_preds, fine_preds)):\n            rows.append({\n                "image": img_path.name, "det_idx": i, "score": float(s),\n                "x1": float(b[0]), "y1": float(b[1]), "x2": float(b[2]), "y2": float(b[3]),\n                "coarse_pred_idx": int(c), "coarse_pred_label": COARSE_CLASSES[int(c)],\n                "fine_pred_idx": int(f), "fine_pred_label": fine_classes[int(f)] if fine_classes and int(f) >= 0 else None,\n            })\n\n    elapsed = time.perf_counter() - t0\n    fps = len(img_paths) / max(elapsed, 1e-9)\n\n    coarse_maps = []\n    for thr in IOU_THRESHOLDS:\n        ap, _, _ = compute_map(pred_boxes_all, pred_scores_all, pred_coarse_all, gt_boxes_all, gt_coarse_all, len(COARSE_CLASSES), thr)\n        coarse_maps.append(ap.mean())\n    ap50, ar50, gt_counts = compute_map(pred_boxes_all, pred_scores_all, pred_coarse_all, gt_boxes_all, gt_coarse_all, len(COARSE_CLASSES), 0.5)\n\n    result = {\n        "path": "B_cascade",\n        "mAP50_coarse": round(float(coarse_maps[0]), 5),\n        "mAP50_95_coarse": round(float(np.mean(coarse_maps)), 5),\n        "fps": round(fps, 2),\n        "n_images": len(img_paths),\n        "det_conf": args.det_conf,\n        "det_iou": args.det_iou,\n    }\n    for i, cls in enumerate(COARSE_CLASSES):\n        result[f"AP50_coarse_{cls}"] = round(float(ap50[i]), 5)\n        result[f"AR50_coarse_{cls}"] = round(float(ar50[i]), 5)\n        result[f"n_gt_coarse_{cls}"] = int(gt_counts[i])\n\n    if has_fine_gt and fine_classes:\n        fine_maps = []\n        for thr in IOU_THRESHOLDS:\n            ap, _, _ = compute_map(pred_boxes_all, pred_scores_all, pred_fine_all, gt_boxes_all, gt_fine_all, len(fine_classes), thr)\n            fine_maps.append(ap.mean())\n        result["mAP50_fine"] = round(float(fine_maps[0]), 5)\n        result["mAP50_95_fine"] = round(float(np.mean(fine_maps)), 5)\n\n    (args.output / "path_B_cascade_summary.json").write_text(json.dumps(result, indent=2))\n    if rows:\n        import pandas as pd\n        pd.DataFrame(rows).to_csv(args.output / "path_B_cascade_predictions.csv", index=False)\n\n    print("\\nPATH B CASCADE — FINAL")\n    print(json.dumps(result, indent=2))\n    return result\n\n\ndef parse_args():\n    p = argparse.ArgumentParser(description="Evaluate detector + Path B coarse->fine cascade")\n    p.add_argument("--detector_weights", type=Path, required=True)\n    p.add_argument("--cascade_dir", type=Path, required=True)\n    p.add_argument("--data_yaml", type=Path, required=True)\n    p.add_argument("--output", type=Path, default=Path("results_path_B_cascade"))\n    p.add_argument("--device", type=str, default="0")\n    p.add_argument("--imgsz", type=int, default=640)\n    p.add_argument("--det_conf", type=float, default=0.001)\n    p.add_argument("--det_iou", type=float, default=0.6)\n    return p.parse_args()\n\n\nif __name__ == "__main__":\n    evaluate(parse_args())\n'

if _FLAG in sys.argv:
    sys.argv = [arg for arg in sys.argv if arg != _FLAG]
    globals_dict = {"__name__": "__main__", "__file__": __file__}
    exec(compile(_CASCADE_CODE, __file__, "exec"), globals_dict)
else:
    globals_dict = {"__name__": "__main__", "__file__": __file__}
    exec(compile(_LEGACY_CODE, __file__, "exec"), globals_dict)
